                try {
                    Thread.sleep(TimeUnit.SECONDS.toMillis(10));
                } catch (InterruptedException e1) {
                    log.error("Failed to sleep");
                }
                log.info("Stream {} is not active yet, exception: ", streamName, e);
            }
        }
    }
