        // later processing in hope that the type can be resolved in a later round.
        deferredTypes.add(element.getQualifiedName().toString());
      } catch (AutoMatterProcessorException e) {
        e.print(messager);
      } catch (Exception e) {
        messager.printMessage(ERROR, e.getMessage());
