     */
    @CheckForNull
    public JiraIssue getIssue(final String id) throws IOException {
        try {

            Issue issue = issueCache.get(id, new Callable<Issue>() {
                public Issue call() throws Exception {
                    JiraSession session = getSession();
                    Issue issue = null;
                    if (session != null) {
                        issue = session.getIssue(id);
                    }
                    return issue;
                }
