  public int getOutlineLevel() {
    throw new NotSupportedException();
  }

  /**
   * Not supported
   */
  @Override
  public void shiftCellsRight(int firstShiftColumnIndex, int lastShiftColumnIndex, int step) {
    throw new NotSupportedException();
  }

  /**
   * Not supported
   */
