public interface Context {

	enum HTTP_STATUS {
        notFound404, ok200, forbidden403, teapot418, badRequest400, noContent204, created201
	}

	/**
	 * Returns the uri as seen by the server.
	 * 
	 * http://example.com/index would return
	 * "/index".
	 * 
	 * @return the uri as seen by the server
	 */
    String getRequestUri();

    /**
     * Returns the flash cookie. Flash cookies only live for one request.
     * Good uses are error messages to display. Almost everything else
     * is bad use of Flash Cookies.
     * 
     * A FlashCookie is usually not signed. Don't trust the content.
     * 
     * @return the flash cookie of that request.
     */
    FlashCookie getFlashCookie();

    /**
     * Returns the client side session. It is a cookie. Therefore you
     * cannot store a lot of information inside the cookie. This is by intention.
     * 
     * If you have the feeling that the session cookie is too small for what you want
     * to achieve thing again. Most likely your design is wrong.
     * 
     * @return the Session of that request / response cycle.
     */
	SessionCookie getSessionCookie();

	/**
	 * Simply redirect to another url.
	 * 
	 * @param url The url to redirect to
	 */
	void redirect(String url);

	/**
	 * Set the response content type.
	 * 
	 * The content type is usually also important because the rendering engine
	 * uses that contentType to determein which engine to chose.
	 * 
	 * call render() on application/json and the json render engine will be used
	 * call render() on text/html and the html render engine will be used.
	 * 
	 * @param contentType examples are "application/json" or "text/html".
	 */
	void setContentType(String contentType);

	/**
	 * Th explicitTemplateName is a fully qualified name of a template
	 * from the root of the package. It includes the suffix of
	 * a template (eg ftl.html).
	 * 
	 * An example is:
	 * "/views/forbidden403.ftl.html"
	 * or
	 * "/views/ApplicationController/index.ftl.html"
	 * 
	 * @param explicitTemplateName is something like "/views/ApplicationController/index.ftl.html"
	 * @return the very same Context for chaining.
	 */
	Context template(String explicitTemplateName);

    /**
     * Get the underlying HTTP servlet request
     * 
     * @Deprecated because it directly refers to the servlet api.
     * And usually we don't want that.
     * 
     * If you are missing something you cannot find in context please
     * suggest it. getHttpServletResponse will be removed at some point.
     *
     * @return The HTTP servlet request
     */
	@Deprecated
	HttpServletRequest getHttpServletRequest();

    /**
     * Get the underlying HTTP servlet response
     * 
     * @Deprecated because it directly refers to the servlet api.
     * And usually we don't want that.
     * 
     * If you are missing something you cannot find in context please
     * suggest it. getHttpServletResponse will be removed at some point.
     *
     * @return The HTTP servlet response
     * 

     */
	@Deprecated
	HttpServletResponse getHttpServletResponse();

    /**
     * Set the status code for the response
     *
     * @param httpStatus The status code
     * @return This context
     */
	Context status(HTTP_STATUS httpStatus);

    /**
     * Get the path parameter for the given key
     *
     * @param key The key of the path parameter
     * @return The path parameter, or null if no such path parameter is defined
     */
	String getPathParameter(String key);

	/**
	 * Get the path parameter for the given key and convert it to Integer.
	 * 
	 * @param key
	 *            the key of the path parameter
	 * @return the numeric path parameter, or null of no such path parameter is
	 *         defined, or if it cannot be parsed to int
	 */
	Integer getPathParameterNumeric(String key);

    /**
     * Get the parameter with the given key from the request.  The parameter may either be a query parameter, or in the
     * case of form submissions, may be a form parameter
     *
     * @param key The key of the parameter
     * @return The value, or null if no parameter was found
     */
    String getParameter(String key);

	/**
	 * Same like {@link #getParameter(String)}, but returns given defaultValue
	 * instead of null in case parameter cannot be found
	 * 
	 * @param key
	 * @param defaultValue
	 * @return
	 */
	String getParameter(String key, String defaultValue);

	/**
	 * Same like {@link #getParameter(String, String)}, but converts the
	 * parameter to Integer if found.
	 * 
	 * @param key
	 * @param defaultValue
	 * @return
	 */
	Integer getParameterNumeric(String key, Integer defaultValue);

    /**
     * Get all the parameters from the request
     *
     * @return The parameters
     */
    Map<String, String[]> getParameters();

    /**
     * Get the request header with the given name
     *
     * @return The header value
     */
    String getHeader(String name);

    /**
     * Get all the headers from the request
     *
     * @return The headers
     */
    Map<String, String> getHeaders();

    /**
     * Get the cookie value from the request, if defined
     *
     * @param name The name of the cookie
     * @return The cookie value, or null if the cookie was not found
     */
    String getCookieValue(String name);

    /**
     * Set a cookie
     *
     * @param cookie the cookie to set
     */
    void addCookie(Cookie cookie);

    /**
     * Unset the cookie with the given name
     *
     * @param name The name of the cookie to unset
     */
    void unsetCookie(String name);

    /**
     * Get the name of the template that will be rendered for this request
     *
     * @param suffix The default suffix to add if computing the template name by convention
     * @return The name of the template to be rendered
     */
	String getTemplateName(String suffix);

    /**
     * Render the result stored in this context
     */
	void render();

    /**
     * Render the given object, using the appropriate template engine for the content type
     *
     * @param object The object to render
     * @throws IllegalArgumentException If no template engine could be found for the content type
     */
    void render(Object object);

    ///////////////////////////////////////////////////////////////////////////
	// Convenience Methods to render a specific type. Html, Json and maybe Xml
	// Uses no content negotation whatsoever
	///////////////////////////////////////////////////////////////////////////
	/**
	 * Renders something as text/html. Either uses a predefined template or
	 * the template determined by auto configuration.
	 */
	void renderHtml();

	/**
	 * Renders this object. Most likely the render engine will take a Map.
	 * The default rendering engine is Freemarker. And Fremarker
	 * will take a map of objects.
	 * 
	 * @param object The object to render as Html
	 */
	void renderHtml(Object object);

	/**
	 * Render the object as json. Uses the underlying Json implementation.
	 * By default we are using Gson. And Gson is accepting any Object and will
	 * transform it into a Json response.
	 * 
	 * @param object The object to render as Json
	 */
	void renderJson(Object object);

	///////////////////////////////////////////////////////////////////////////
	// Allows to get the nicely parsed content of the request.
	// For instance if the content is a json you could simply get the json
	// as Java object.
	///////////////////////////////////////////////////////////////////////////
	/**
	 * This will give you the request body nicely parsed. You can register your
	 * own parsers depending on the request type.
	 * 
	 * Have a look at {@link ninja.bodyparser.BodyParserEngine} {@link BodyParserEngineJson}
	 * and {@link BodyParserEngineManager}
	 * 
	 * @param classOfT The class of the result.
	 * @return The parsed request or null if something went wrong.
	 */
	<T> T parseBody(Class<T> classOfT);

    /**
     * Indicate that this request will be handled asynchronously
     */
    void handleAsync();

    /**
     * Indicate that request processing of an async request is complete
     */
    void requestComplete();

    void controllerReturned();

}

package ninja;

import java.io.IOException;
import java.util.Enumeration;
import java.util.HashMap;
import java.util.Map;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

import org.slf4j.Logger;

import ninja.async.AsyncStrategy;
import ninja.async.AsyncStrategyFactoryHolder;
import ninja.bodyparser.BodyParserEngine;
import ninja.bodyparser.BodyParserEngineManager;
import ninja.session.FlashCookie;
import ninja.session.SessionCookie;
import ninja.template.TemplateEngine;
import ninja.template.TemplateEngineManager;
import ninja.utils.CookieHelper;
import ninja.utils.NinjaConstant;

import com.google.inject.Inject;

public class ContextImpl implements Context {

	private HttpServletRequest httpServletRequest;

	private HttpServletResponse httpServletResponse;

    private Route route;

	// * if set this template is used. otherwise the default mapping **/
	private String templateOverride = null;

	private HTTP_STATUS httpStatus;

	public String contentType;

    private AsyncStrategy asyncStrategy;
    private final Object asyncLock = new Object();

	private final TemplateEngineManager templateEngineManager;

	private final BodyParserEngineManager bodyParserEngineManager;

	private final FlashCookie flashCookie;

	private final SessionCookie sessionCookie;

	private final Logger logger;

	@Inject
	public ContextImpl(
			BodyParserEngineManager bodyParserEngineManager,
			FlashCookie flashCookie,
			Logger logger,
			SessionCookie sessionCookie,
			TemplateEngineManager templateEngineManager) {

		this.bodyParserEngineManager = bodyParserEngineManager;
		this.flashCookie = flashCookie;
		this.logger = logger;
		this.sessionCookie = sessionCookie;
		this.templateEngineManager = templateEngineManager;

		this.httpStatus = HTTP_STATUS.ok200;
	}

	public void init(HttpServletRequest httpServletRequest,
			HttpServletResponse httpServletResponse) {
		this.httpServletRequest = httpServletRequest;
		this.httpServletResponse = httpServletResponse;

		// init flash scope:
		flashCookie.init(this);

		// init session scope:
		sessionCookie.init(this);

	}

    public void setRoute(Route route) {
        this.route = route;
    }

	public HttpServletRequest getHttpServletRequest() {
		return httpServletRequest;
	}

	public HttpServletResponse getHttpServletResponse() {
		return this.httpServletResponse;
	}

	@Override
	public Context template(String explicitTemplateName) {
		this.templateOverride = explicitTemplateName;
		return this;
	}

	@Override
	public Context status(HTTP_STATUS httpStatus) {
		this.httpStatus = httpStatus;
		return this;
	}

	@Override
	public String getPathParameter(String key) {
		return route.getParameters(httpServletRequest.getServletPath())
				.get(key);
	}

    @Override
    public Integer getPathParameterNumeric(String key) {
        String parameter = getPathParameter(key);

        try {
            return Integer.parseInt(parameter);
        } catch (Exception e) {
            return null;
        }
    }

    @Override
    public String getParameter(String key) {
        return httpServletRequest.getParameter(key);
    }

	@Override
	public String getParameter(String key, String defaultValue) {
		String parameter = getParameter(key);

		if (parameter == null) {
			parameter = defaultValue;
		}

		return parameter;
	}

	@Override
	public Integer getParameterNumeric(String key, Integer defaultValue) {
		String parameter = getParameter(key);

		try {
			return Integer.parseInt(parameter);
		} catch (Exception e) {
			return defaultValue;
		}
	}

    @Override
    public Map<String, String[]> getParameters() {
        return httpServletRequest.getParameterMap();
    }

    @Override
    public String getHeader(String name) {
        return httpServletRequest.getHeader(name);
    }

    @Override
    public Map<String, String> getHeaders() {
        Map<String, String> headers = new HashMap<String, String>();
        Enumeration<String> enumeration = httpServletRequest.getHeaderNames();
        while (enumeration.hasMoreElements()) {
            String name = enumeration.nextElement();
            headers.put(name, httpServletRequest.getHeader(name));
        }
        return headers;
    }

    @Override
    public String getCookieValue(String name) {
        return CookieHelper.getCookieValue(name, httpServletRequest.getCookies());
    }

    @Override
    public void addCookie(ninja.Cookie cookie) {
        httpServletResponse.addCookie(CookieHelper.convertNinjaCookieToServletCookie(cookie));
    }

    @Override
    public void unsetCookie(String name) {
        httpServletResponse.addCookie(new Cookie(name, null));
    }

    @Override
	public void redirect(String url) {

		try {
			httpServletResponse.sendRedirect(url);
		} catch (IOException e) {
			logger.error("Error while calling redirect on the context", e);
		}

	}

	@Override
	public void render() {

		render(null);

	}

	@Override
	public void render(Object object) {

		finalizeResponseHeaders(contentType);

        if (contentType != null) {
            TemplateEngine templateEngine = templateEngineManager
                    .getTemplateEngineForContentType(contentType);

            if (templateEngine == null) {
                throw new IllegalArgumentException("No template engine found for content type " + contentType);
            }

            templateEngine.invoke(this, object);
        }
	}

	@Override
	public void renderHtml() {
		renderHtml(new HashMap<String, String>());
	}

	@Override
	public void renderHtml(Object object) {
		finalizeResponseHeaders(ContentTypes.TEXT_HTML);

		TemplateEngine templateEngine = templateEngineManager
				.getTemplateEngineForContentType(ContentTypes.TEXT_HTML);

		templateEngine.invoke(this, object);

	}

	@Override
	public void renderJson(Object object) {

		finalizeResponseHeaders(ContentTypes.APPLICATION_JSON);

		TemplateEngine templateEngine = templateEngineManager
				.getTemplateEngineForContentType(ContentTypes.APPLICATION_JSON);

		templateEngine.invoke(this, object);


	}

	private void finalizeResponseHeaders(String contentType) {
        if (contentType != null) {
            setContentType(contentType);
        }
		setStatusOnResponse(httpStatus);

		flashCookie.save(this);
		sessionCookie.save(this);

	}

	/**
	 * set status on response finally...
	 * 
	 * @param httpStatus
	 */
	private void setStatusOnResponse(HTTP_STATUS httpStatus) {

		if (httpStatus.equals(HTTP_STATUS.ok200)) {
			httpServletResponse.setStatus(200);
		} else if (httpStatus.equals(HTTP_STATUS.notFound404)) {
			httpServletResponse.setStatus(404);
		} else if (httpStatus.equals(HTTP_STATUS.forbidden403)) {
			httpServletResponse.setStatus(403);
		} else if (httpStatus.equals(HTTP_STATUS.teapot418)) {
			httpServletResponse.setStatus(418);
		} else if (httpStatus.equals(HTTP_STATUS.badRequest400)) {
			httpServletResponse.setStatus(400);
		} else if (httpStatus.equals(HTTP_STATUS.noContent204)) {
			httpServletResponse.setStatus(204);
		} else if (httpStatus.equals(HTTP_STATUS.created201)) {
			httpServletResponse.setStatus(201);
		}

	}

	@Override
	public void setContentType(String contentType) {
	    this.contentType = contentType;
		httpServletResponse.setContentType(contentType);

	}

	@Override
	public String getTemplateName(String suffix) {
        if (templateOverride == null) {
            Class controller = route.getControllerClass();

            // Calculate the correct path of the template.
            // We always assume the template in the subdir "views"

            // 1) If we are in the main project => /views/ControllerName/templateName.ftl.html
            // 2) If we are in a plugin / subproject
            //    => some/packages/submoduleName/views/ControllerName/templateName.ftl.html

            // So let's calculate the parent package of the controller:
            String controllerPackageName = controller.getPackage().getName();
            // This results in something like controllers or some.package.controllers

            // Let's remove "controllers" so we cat all parent packages:
            String parentPackageOfController = controllerPackageName.replaceAll(NinjaConstant.CONTROLLERS_DIR, "");

            // And now we rewrite everything from "." notation to directories /
            String parentControllerPackageAsPath = parentPackageOfController.replaceAll("\\.", "/");


            // and the final path of the controller will be something like:
            // some/package/views/ControllerName/templateName.ftl.html
            return String.format("%sviews/%s/%s%s", parentControllerPackageAsPath, controller
                    .getSimpleName(), route.getControllerMethod().getName(), suffix);
        }
		return templateOverride;
	}

	@Override
	public <T> T parseBody(Class<T> classOfT) {

		BodyParserEngine bodyParserEngine = bodyParserEngineManager
				.getBodyParserEngineForContentType(ContentTypes.APPLICATION_JSON);

		if (bodyParserEngine == null) {
			return null;
		}

		return bodyParserEngine.invoke(this, classOfT);

	}

	@Override
	public FlashCookie getFlashCookie() {
		return flashCookie;
	}

	@Override
	public SessionCookie getSessionCookie() {
		return sessionCookie;
	}

    @Override
    public String getRequestUri() {
        return getHttpServletRequest().getRequestURI();
    }

    @Override
    public void handleAsync() {
        synchronized (asyncLock) {
            if (asyncStrategy == null) {
                asyncStrategy = AsyncStrategyFactoryHolder.INSTANCE.createStrategy(httpServletRequest);
                asyncStrategy.handleAsync();
            }
        }
    }

    @Override
    public void requestComplete() {
        synchronized (asyncLock) {
            if (asyncStrategy == null) {
                throw new IllegalStateException("Request complete called on non async request");
            }
            asyncStrategy.requestComplete();
        }
    }

    /**
     * Used to indicate that the controller has finished executing
     */
    public void controllerReturned() {
        synchronized (asyncLock) {
            if (asyncStrategy != null) {
                asyncStrategy.controllerReturned();
            }
        }
    }
}

