        ensureDimensionsAreCorrect(rows, columns);

        if (this.rows == rows && this.columns == columns) {
            return copy();
        }

        if (this.rows >= rows && this.columns >= columns) {

            double $values[] = new double[align(cardinality)];
            int $columnIndices[] = new int[align(cardinality)];
